        if not args and not kw:
            return self._xmargin, self._ymargin, self._zmargin

        tight = kw.pop('tight', True)
        mx = kw.pop('x', None)
        my = kw.pop('y', None)
        mz = kw.pop('z', None)
        if not args:
            pass
        elif len(args) == 1:
            mx = my = mz = args[0]
        elif len(args) == 2:
            warnings.warn(
                "Passing exactly two positional arguments to Axes3D.margins "
                "is deprecated.  If needed, pass them as keyword arguments "
                "instead", cbook.mplDeprecation)
            mx, my = args
        elif len(args) == 3:
            mx, my, mz = args
        else:
            raise ValueError(
                "Axes3D.margins takes at most three positional arguments")
        if mx is not None:
            self.set_xmargin(mx)
        if my is not None:
            self.set_ymargin(my)
        if mz is not None:
            self.set_zmargin(mz)

        scalex = mx is not None
        scaley = my is not None
        scalez = mz is not None

        self.autoscale_view(tight=tight, scalex=scalex, scaley=scaley,
                                         scalez=scalez)

