def update(self, camera=True):



        confirm_timer = Timer(5, count=10).start()
        while 1:
            try:
                success = self._update(camera=camera)
                if success:
                    break
                else:
                    confirm_timer.reset()
                    continue
            except MapDetectionError:
                if confirm_timer.reached():
                    raise
                else:
                    continue

