            if _HAS_SENDFILE:
                try:
                    _fastcopy_sendfile(fsrc, fdst)
                    return dst
                except _GiveupOnFastCopy:
                    pass

            if _HAS_FCOPYFILE:
                try:
                    _fastcopy_osx(fsrc, fdst, posix._COPYFILE_DATA)
                    return dst
                except _GiveupOnFastCopy:
                    pass

            _copybinfileobj(fsrc, fdst)

    return dst

