def assertAlmostEqual(self, first, second, *, places=7, msg=None):


        if first == second:
            # shortcut for inf
            return
        if round(abs(second-first), places) != 0:
            standardMsg = '%s != %s within %r places' % (safe_repr(first),
                                                          safe_repr(second),
                                                          places)
            msg = self._formatMessage(msg, standardMsg)
