def count_params(self):




        size = 0
        for name, param in self.namedparams():
            if param.array is None:
                warnings.warn(
                    '{} has not been initialized, so the resulting size will '
                    'not include the number of parameters in it.'.format(name))
                continue
            size += param.size
        return size

